PRAGMA foreign_keys=ON;
CREATE TABLE IF NOT EXISTS users(id INTEGER PRIMARY KEY AUTOINCREMENT,employee_id TEXT UNIQUE,name TEXT NOT NULL,email TEXT NOT NULL UNIQUE,password_hash TEXT NOT NULL,password_salt TEXT NOT NULL,role TEXT NOT NULL CHECK(role IN('super_admin','admin','department_admin','editor','employee')),is_active INTEGER NOT NULL DEFAULT 1,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS departments(id INTEGER PRIMARY KEY AUTOINCREMENT,name_bn TEXT NOT NULL,name_en TEXT,type TEXT,phone TEXT,email TEXT,website TEXT);
CREATE TABLE IF NOT EXISTS employees(id INTEGER PRIMARY KEY AUTOINCREMENT,user_id INTEGER UNIQUE,employee_id TEXT NOT NULL UNIQUE,name_bn TEXT NOT NULL,name_en TEXT,date_of_birth TEXT,mobile TEXT,email TEXT,designation TEXT,department_id INTEGER,grade INTEGER,basic_salary REAL,joining_date TEXT,current_position TEXT,current_position_joining_date TEXT,service_status TEXT DEFAULT 'active',employment_type TEXT,photo_key TEXT,FOREIGN KEY(user_id) REFERENCES users(id),FOREIGN KEY(department_id) REFERENCES departments(id));
CREATE TABLE IF NOT EXISTS sessions(id INTEGER PRIMARY KEY AUTOINCREMENT,user_id INTEGER NOT NULL,token_hash TEXT NOT NULL UNIQUE,expires_at TEXT NOT NULL,created_at TEXT DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS service_history(id INTEGER PRIMARY KEY AUTOINCREMENT,employee_id INTEGER NOT NULL,event_type TEXT NOT NULL,event_date TEXT NOT NULL,title TEXT,grade INTEGER,notes TEXT,FOREIGN KEY(employee_id) REFERENCES employees(id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS salary_scales(id INTEGER PRIMARY KEY AUTOINCREMENT,title TEXT NOT NULL,effective_date TEXT NOT NULL,is_active INTEGER NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS salary_scale_stages(id INTEGER PRIMARY KEY AUTOINCREMENT,salary_scale_id INTEGER NOT NULL,grade INTEGER NOT NULL,stage_no INTEGER NOT NULL,basic_amount REAL NOT NULL,UNIQUE(salary_scale_id,grade,stage_no));
CREATE TABLE IF NOT EXISTS promotion_rules(id INTEGER PRIMARY KEY AUTOINCREMENT,current_grade INTEGER NOT NULL,next_grade INTEGER,stream TEXT DEFAULT 'general',education_key TEXT,required_years REAL,computer_required INTEGER DEFAULT 0,acr_required INTEGER DEFAULT 0,reference_text TEXT,effective_date TEXT,is_active INTEGER DEFAULT 1);
CREATE TABLE IF NOT EXISTS notices(id INTEGER PRIMARY KEY AUTOINCREMENT,title TEXT NOT NULL,category TEXT,description TEXT,publish_date TEXT,target_group TEXT,reference_no TEXT,is_pinned INTEGER DEFAULT 0);
CREATE TABLE IF NOT EXISTS policies(id INTEGER PRIMARY KEY AUTOINCREMENT,title TEXT NOT NULL,category TEXT,body TEXT NOT NULL,source_reference TEXT,policy_date TEXT);
CREATE TABLE IF NOT EXISTS audit_logs(id INTEGER PRIMARY KEY AUTOINCREMENT,user_id INTEGER,action TEXT NOT NULL,entity_type TEXT,entity_id TEXT,metadata TEXT,created_at TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX IF NOT EXISTS idx_users_email ON users(email);CREATE INDEX IF NOT EXISTS idx_sessions_token ON sessions(token_hash);CREATE INDEX IF NOT EXISTS idx_employees_department ON employees(department_id);
